
package com.drewweise.tend.food.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

/**
 * Represents a Food used as an ingredient in another Food.
 *
 * Example:
 * Chicken Alfredo contains:
 * - 200 g chicken breast
 * - 150 g fettuccine
 * - 30 g Parmesan
 *
 * Each ingredient is itself a Food record.
 *
 * This allows Foods to be composed of other Foods
 * without needing separate Recipe and Ingredient entities.
 */
@Entity
@Table(name = "food_ingredients")
public class FoodIngredient {

    // Primary key, automatically generated by MySQL.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "food_ingredient_id")
    private Integer foodIngredientId;

    /**
     * The Food that contains this ingredient.
     *
     * Example: Chicken Alfredo.
     *
     * Multiple FoodIngredient records can reference
     * the same parent Food.
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "parent_food_id", nullable = false)
    private Food parentFood;

    /**
     * The Food being used as an ingredient.
     *
     * Example: Chicken breast.
     *
     * The same ingredient Food can be reused
     * in many different meals.
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "ingredient_food_id", nullable = false)
    private Food ingredientFood;

    /**
     * Amount of the ingredient used.
     *
     * Example: 200, 150, or 30.
     *
     * BigDecimal provides precise decimal values.
     */
    @Column(name = "quantity", nullable = false)
    private BigDecimal quantity;

    /**
     * Unit used to measure the ingredient.
     *
     * Examples: g, ml, cup, slice.
     *
     * We'll handle unit conversions later when
     * implementing nutritional calculations.
     */
    @Column(name = "unit", nullable = false)
    private String unit;

    // Required by JPA/Hibernate when loading records.
    protected FoodIngredient() {
    }

    /**
     * Creates an ingredient relationship between two Foods.
     *
     * The parent Food and ingredient Food must be different.
     * Quantity must be positive, and unit cannot be blank.
     */
    public FoodIngredient(
            Food parentFood,
            Food ingredientFood,
            BigDecimal quantity,
            String unit
    ) {
        if (parentFood == null || ingredientFood == null) {
            throw new IllegalArgumentException(
                    "Parent food and ingredient food cannot be null"
            );
        }

        if (parentFood == ingredientFood ||
                (parentFood.getFoodId() != null &&
                        parentFood.getFoodId().equals(ingredientFood.getFoodId()))) {
            throw new IllegalArgumentException(
                    "A Food cannot contain itself as an ingredient"
            );
        }

        this.parentFood = parentFood;
        this.ingredientFood = ingredientFood;

        setQuantity(quantity);
        setUnit(unit);
    }

    // GETTERS

    public Integer getFoodIngredientId() {
        return foodIngredientId;
    }

    public Food getParentFood() {
        return parentFood;
    }

    public Food getIngredientFood() {
        return ingredientFood;
    }

    public BigDecimal getQuantity() {
        return quantity;
    }

    public String getUnit() {
        return unit;
    }

    // SETTERS

    /**
     * Updates the ingredient quantity.
     *
     * Rejects null, zero, and negative values.
     */
    public void setQuantity(BigDecimal quantity) {
        if (quantity == null ||
                quantity.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException(
                    "Ingredient quantity must be greater than zero"
            );
        }

        this.quantity = quantity;
    }

    /**
     * Updates the ingredient measurement unit.
     */
    public void setUnit(String unit) {
        if (unit == null || unit.isBlank()) {
            throw new IllegalArgumentException(
                    "Ingredient unit cannot be blank"
            );
        }

        this.unit = unit;
    }
}
